select * from (
    select  pp.id,pp.month_plan_aps_version,pp.bom_Data_Version,pp.material_code,pp.spec_desc,pp.embryo_code,pp.quality_grade,pp.storage_location,pp.special_requirements,pp.expected_excess_arrears,pp.theory_production_plan,pp.actual_arrangement,pp.balance,pp.lh_machine_code,pp.lh_machine_name,pp.cx_machine_code,pp.cx_machine_name,pp.product_qty1,pp.finish_qty1,pp.product_qty2,pp.finish_qty2,pp.product_qty3,pp.finish_qty3,pp.product_qty4,pp.finish_qty4,pp.product_qty5,pp.finish_qty5,pp.product_qty6,pp.finish_qty6,pp.product_qty7,pp.finish_qty7,pp.product_qty8,pp.finish_qty8,pp.product_qty9,pp.finish_qty9,pp.product_qty10,pp.finish_qty10,pp.product_qty11,pp.finish_qty11,pp.product_qty12,pp.finish_qty12,pp.product_qty13,pp.finish_qty13,pp.product_qty14,pp.finish_qty14,pp.product_qty15,pp.finish_qty15,pp.product_qty16,pp.finish_qty16,pp.product_qty17,pp.finish_qty17,pp.product_qty18,pp.finish_qty18,pp.product_qty19,pp.finish_qty19,pp.product_qty20,pp.finish_qty20,pp.product_qty21,pp.finish_qty21,pp.product_qty22,pp.finish_qty22,pp.product_qty23,pp.finish_qty23,pp.product_qty24,pp.finish_qty24,pp.product_qty25,pp.finish_qty25,pp.product_qty26,pp.finish_qty26,pp.product_qty27,pp.finish_qty27,pp.product_qty28,pp.finish_qty28,pp.product_qty29,pp.finish_qty29,pp.product_qty30,pp.finish_qty30,pp.product_qty31,pp.finish_qty31,pp.create_by,pp.create_time,pp.update_by,pp.update_time,pp.del_flag,pp.remark,pp.spec_dimension,pp.storage_location_desc,pp.actual_over_production,pp.plan_modify_qty,pp.begin_date,pp.end_date,pp.data_source,pp.plan_seq,
            pm.year,pm.month,pm.IS_FINALIZED
    from t_mdm_month_prod_plan pp, T_MDM_MONTH_PLAN_MAIN pm
    where pp.del_flag = '0'
    and pm.del_flag = '0'
    and pp.MONTH_PLAN_APS_VERSION=pm.MONTH_PLAN_APS_VERSION
    and pp.month_plan_aps_version =#{monthPlanApsVersion}
    and instr(pp.material_code,#{materialCode}) > 0 
    and instr(pp.embryo_code,#{embryoCode}) > 0
    and pp.cx_machine_code = #{cxMachineCode}
    and pp.lh_machine_code = #{lhMachineCode}
    and pp.quality_Grade = #{qualityGrade}
    and pp.storage_Location = #{storageLocation}
    and pm.year = #{year}
    and pm.month = #{month}
    and pm.IS_FINALIZED = #{isFinamized}
    and pp.bom_Data_Version is null
    and pp.bom_Data_Version is not null
    and INSTR(pp.bom_Data_Version, #{bomDataVersion}) > 0

        order by pp.month_plan_aps_version,pp.material_code,pp.embryo_code,pp.cx_machine_code desc

) t

    order by ${orderStr}

select  pp.material_code,pp.embryo_code,sum(pp.expected_excess_arrears) as expected_excess_arrears
from t_mdm_month_prod_plan pp, T_MDM_MONTH_PLAN_MAIN pm
where pp.del_flag = '0'
and pm.del_flag = '0'
and pp.MONTH_PLAN_APS_VERSION=pm.MONTH_PLAN_APS_VERSION
and pp.month_plan_aps_version =#{monthPlanApsVersion}
and instr(pp.material_code,#{materialCode}) > 0 
and instr(pp.embryo_code,#{embryoCode}) > 0
and pp.cx_machine_code = #{cxMachineCode}
and pp.lh_machine_code = #{lhMachineCode}
and pp.quality_Grade = #{qualityGrade}
and pp.storage_Location = #{storageLocation}
and pm.year = #{year}
and pm.month = #{month}
and pm.IS_FINALIZED = #{isFinamized}
group by pp.material_code,pp.embryo_code

select pp.material_code, pp.embryo_code,
      sum(NVL( pp.actual_Over_Production, 0 ) - NVL( pp.expected_excess_arrears, 0 )) AS actual_Over_Production
from t_mdm_month_prod_plan pp, T_MDM_MONTH_PLAN_MAIN pm
where pp.del_flag = '0'
and pm.del_flag = '0'
and pp.MONTH_PLAN_APS_VERSION=pm.MONTH_PLAN_APS_VERSION
and pp.month_plan_aps_version =#{monthPlanApsVersion}
and instr(pp.material_code,#{materialCode}) > 0 
and instr(pp.embryo_code,#{embryoCode}) > 0
and pp.cx_machine_code = #{cxMachineCode}
and pp.lh_machine_code = #{lhMachineCode}
and pp.quality_Grade = #{qualityGrade}
and pp.storage_Location = #{storageLocation}
and pm.year = #{year}
and pm.month = #{month}
and pm.IS_FINALIZED = #{isFinamized}
group by pp.material_code,pp.embryo_code

select  pm.year,pm.month,pp.material_code,pp.quality_grade,pp.storage_location,sum(pp.EXPECTED_EXCESS_ARREARS) as EXPECTED_EXCESS_ARREARS
from t_mdm_month_prod_plan pp, T_MDM_MONTH_PLAN_MAIN pm
where pp.del_flag = '0' and pm.del_flag = '0' and pp.MONTH_PLAN_APS_VERSION=pm.MONTH_PLAN_APS_VERSION
and pp.month_plan_aps_version = #{monthPlanApsVersion}
and instr(pp.material_code,#{materialCode}) > 0 
and instr(pp.embryo_code,#{embryoCode}) > 0
and pp.cx_machine_code = #{cxMachineCode}
and pp.lh_machine_code = #{lhMachineCode}
and pp.quality_Grade = #{qualityGrade}
and pp.storage_Location = #{storageLocation}
and pm.year = #{year}
and pm.month = #{month}
and pm.IS_FINALIZED = #{isFinamized}
GROUP BY pm.year,pm.month,pp.material_code,pp.quality_grade,pp.storage_location

